export function reverseReviewedSchema58(path:string,bytes:Uint8Array):Buffer {
 const delta=reviewedSchema58SourceDeltas.find(item=>item.path===path);if(!delta)return Buffer.from(bytes);
 const sha=(value:Uint8Array)=>createHash('sha256').update(value).digest('hex');
 if(sha(bytes)===delta.previousSha256)return Buffer.from(bytes);
 let source=Buffer.from(bytes).toString('utf8');
 for(const inverse of delta.inverse){assert.equal(source.split(inverse.after).length-1,1,`Baseline dependency changed: ${path}; reviewed58 edit must occur exactly once`);source=source.replace(inverse.after,inverse.before);}
 const recovered=Buffer.from(source);assert.equal(sha(recovered),delta.previousSha256,`Baseline dependency changed: ${path}; unreviewed58 source drift`);return recovered;
}
